#!/usr/bin/env node
/**
 * Build `src/client/marks.tsx` from the artwork in `assets/`.
 *
 *   node plugins/dsh-link-brand/scripts/gen-marks.mjs
 *
 * The artwork is the design's own paths; this script performs the two rewrites
 * an in-app mark needs on top of them:
 *
 * - the ink (`#0F1115`) becomes `currentColor`, so one component is legible on
 *   both of the client's palettes while the ring keeps the design's blue;
 * - the artwork's fixed mask id becomes a per-instance React id, so the sidebar
 *   mark and the hero mark cannot capture each other's mask.
 *
 * The generated file is committed, so `node plugins/build.mjs --check` passes
 * without running this script.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = resolve(HERE, '..')
const ASSETS = join(ROOT, 'assets')
const OUTPUT = join(ROOT, 'src', 'client', 'marks.tsx')

/** Fill the design uses for ink; every other fill (the accent blue, the mask's white and hole) is kept. */
const INK = /fill="#0F1115"/g

/** Read one SVG and return its parts, with path markup ready for JSX. */
function parse(file) {
  const text = readFileSync(join(ASSETS, file), 'utf8')
  const viewBox = /viewBox="([^"]+)"/.exec(text)?.[1]
  const mask = /<mask[^>]*>([\s\S]*?)<\/mask>/.exec(text)?.[1]
  const group = /<g mask="url\(#[^)]*\)">([\s\S]*?)<\/g>/.exec(text)?.[1]
  if (viewBox === undefined || mask === undefined || group === undefined) {
    throw new Error(file + ': expected a viewBox, one mask and one masked group')
  }
  const [width, height] = viewBox.split(/\s+/).slice(2).map(Number)
  const shape = markup => markup.trim().replace(INK, 'fill="currentColor"').replace(/fill-rule=/g, 'fillRule=')
  return {
    file, viewBox, width, height,
    maskRect: shape(/<rect[^>]*\/>/.exec(mask)?.[0] ?? ''),
    maskHole: shape(/<path[^>]*\/>/.exec(mask)?.[0] ?? ''),
    paths: [...group.matchAll(/<path[^>]*\/>/g)].map(match => shape(match[0])),
  }
}

const symbol = parse('symbol-v2.svg')
const wordmark = parse('dsh-link-in-d.svg')

/** Indent a block of markup by one level inside JSX. */
const indent = (markup, pad) => markup.split('\n').map(line => pad + line).join('\n')

const mark = `/**
 * The DSH Link symbol: the ring, the whale and the \`LINK\` stem in one 1:1 badge.
 * @param props - the box to draw in, and the declaring surface's own class.
 * @returns the mark as inline SVG.
 */
export function DshBrandMark({ size = 24, className }: { size?: number; className?: string }) {
  const mask = 'dsh-link-brand-' + useId().replace(/[^A-Za-z0-9_-]/g, '')
  return (
    <svg viewBox="${symbol.viewBox}" width={size} height={size} className={className} fill="none" aria-hidden="true" focusable="false">
      <defs>
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="${symbol.width}" height="${symbol.height}">
          ${symbol.maskRect}
          ${symbol.maskHole}
        </mask>
      </defs>
      <g mask={'url(#' + mask + ')'}>
${indent(symbol.paths.join('\n'), '        ')}
      </g>
    </svg>
  )
}`

const name = `/**
 * The DSH Link wordmark: \`dsh\` with the whale in the \`d\` bowl, then \`LINK\`.
 * @param props - the drawn height in CSS pixels (the width follows the artwork's
 * aspect ratio), and the declaring surface's own class.
 * @returns the wordmark as inline SVG.
 */
export function DshBrandName({ height = 16, className }: { height?: number; className?: string }) {
  const mask = 'dsh-link-brand-' + useId().replace(/[^A-Za-z0-9_-]/g, '')
  const width = Math.round((height * ${wordmark.width} / ${wordmark.height}) * 100) / 100
  return (
    <svg viewBox="${wordmark.viewBox}" width={width} height={height} className={className} fill="none" aria-hidden="true" focusable="false">
      <defs>
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="${wordmark.width}" height="${wordmark.height}">
          ${wordmark.maskRect}
          ${wordmark.maskHole}
        </mask>
      </defs>
      <g mask={'url(#' + mask + ')'}>
${indent(wordmark.paths.join('\n'), '        ')}
      </g>
    </svg>
  )
}`

const file = `/** Generated by scripts/gen-marks.mjs from ${symbol.file} and ${wordmark.file} — edit the SVG, then rerun the script. */
import { useId } from 'react'

${mark}

${name}
`

const before = (() => { try { return readFileSync(OUTPUT, 'utf8') } catch { return undefined } })()
if (before === file) {
  console.log('ok: dsh-link-brand/src/client/marks.tsx (' + file.length + ' bytes, unchanged)')
} else {
  writeFileSync(OUTPUT, file)
  console.log((before === undefined ? 'wrote   ' : 'updated ') + 'dsh-link-brand/src/client/marks.tsx  ' + file.length + ' bytes')
}
